import json
n=30
g=[[0]*n for _ in range(n)]
# Reconstruct the observed tiled input: 5x5 framed cells at pitch 7.
colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
for bi,r in enumerate(starts):
  for bj,c in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        rr,cc=r+dr,c+dc
        if rr<n and cc<n:
          g[rr][cc]=4 if dr in (0,4) or dc in (0,4) else colors[bi][bj]
# Join matching exceptional-color tile centers across each rectangle, only through empty gutters.
# color 3 corners: block rows 0/2, columns 0/3
# color 8 corners: block rows 1/3, columns 1/2
for color, rblocks, cblocks in [(3,(0,2),(0,3)),(8,(1,3),(1,2))]:
  r1,r2=[starts[k]+2 for k in rblocks]
  c1,c2=[starts[k]+2 for k in cblocks]
  for rr in (r1,r2):
    for cc in range(c1+1,c2):
      if g[rr][cc]==0: g[rr][cc]=color
  for cc in (c1,c2):
    for rr in range(r1+1,r2):
      if g[rr][cc]==0: g[rr][cc]=color
print(json.dumps(g,separators=(',',':')))

